"""Генерация бесшовного мира: локации по 10×10 клеток, швы по мировой сетке.

Локации берутся из `data.LOCATIONS` (список может быть динамическим — его
подменяет `engine/storage.py` из настроек панели). Переходы между локациями
строятся по соседству на мировой сетке `world_grid` ({индекс: [wx, wy]}):
соседи по горизонтали сшиваются восток↔запад, по вертикали — север↔юг.
Без сетки работает старая цепочка 0→1→2→… — для совместимости.
"""
import random
from collections import deque

from engine import data
from engine.models import Cell

SIZE = 10
SPAWN = (5, 5)

# Угловые замки — локации 25×25 с цитаделями по углам (см. gen_castle_cells).
# {индекс локации: размер сетки}
DEFAULT_SIZES = {"5": 25, "6": 25, "7": 25, "8": 25}

# Дефолтная раскладка мира — вся мировая карта 10×10.
# По краям — 36 локаций: 4 угла занимают замки 25×25, между ними по 8
# опасных трактов на каждую сторону (промежуточные локации между углами).
# Внутри кольца — стартовые земли и Логово Пожирателя.
DEFAULT_GRID = {
    # ── стартовые земли (внутри кольца) ──
    "0": [4, 4],   # Погост Костров
    "1": [5, 4],   # Тёмный Лес
    "2": [5, 5],   # Заброшенная Крепость
    "3": [4, 5],   # Катакомбы Павших
    "4": [3, 4],   # Логово Пожирателя
    # ── угловые замки 25×25 по углам мировой карты ──
    "5": [0, 0],   # Замок Рассвета (северо-запад)
    "6": [9, 0],   # Замок Теней (северо-восток)
    "7": [0, 9],   # Замок Глубин (юго-запад)
    "8": [9, 9],   # Замок Пепла (юго-восток)
    # ── тракты по краям: 8 на каждую сторону ──
    "9":  [1, 0], "10": [2, 0], "11": [3, 0], "12": [4, 0],
    "13": [5, 0], "14": [6, 0], "15": [7, 0], "16": [8, 0],   # север
    "17": [9, 1], "18": [9, 2], "19": [9, 3], "20": [9, 4],
    "21": [9, 5], "22": [9, 6], "23": [9, 7], "24": [9, 8],   # восток
    "25": [8, 9], "26": [7, 9], "27": [6, 9], "28": [5, 9],
    "29": [4, 9], "30": [3, 9], "31": [2, 9], "32": [1, 9],   # юг
    "33": [0, 8], "34": [0, 7], "35": [0, 6], "36": [0, 5],
    "37": [0, 4], "38": [0, 3], "39": [0, 2], "40": [0, 1],   # запад
}

# Сиды мира: у каждой стороны генерации свой, чтобы правка одного не
# перетряхивала всё остальное. (ключ, подпись, за что отвечает, множитель)
SEEDS = [
    ("terrain",   "🗺 Рельеф",     "стены, тропы и форма локаций",      31),
    ("stories",   "📖 Описания",   "названия и тексты клеток",          97),
    ("mobs",      "👾 Мобы",       "расстановка тварей по клеткам",     193),
    ("chests",    "📦 Сундуки",    "где лежит добыча",                  389),
    ("npc",       "💬 NPC",        "места жителей в безопасных землях", 769),
    ("cataclysm", "🌋 Катаклизмы", "череда бедствий и их размах",       1543),
]
SEED_KEYS = [k for k, _, _, _ in SEEDS]
SEED_LABELS = {k: lbl for k, lbl, _, _ in SEEDS}
SEED_ABOUT = {k: about for k, _, about, _ in SEEDS}
_SEED_MUL = {k: mul for k, _, _, mul in SEEDS}


def seeds_of(settings):
    """Все сиды мира: явно заданные в панели или выведенные из базового.

    Один «Seed» остаётся главным: пока частные сиды не тронуты, они
    выводятся из него, и мир целиком воспроизводим по одному числу.
    """
    base = int(settings.get("seed", 1337) or 0)
    saved = settings.get("seeds") or {}
    out = {}
    for key in SEED_KEYS:
        raw = saved.get(key)
        try:
            val = int(raw)
        except (TypeError, ValueError):
            val = 0
        out[key] = val or ((base * _SEED_MUL[key] + len(key) * 7919) % 2_147_483_647)
    return out


def _connect(cells, start=SPAWN):
    """Отсечь недостижимые от центра клетки."""
    passable = {(c.x, c.y): c for c in cells if c.passable}
    if start not in passable:
        for c in cells:
            if (c.x, c.y) == start:
                c.passable = True
                c.tile = "grass"
                passable[start] = c
    seen, q = {start}, deque([start])
    while q:
        x, y = q.popleft()
        for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            n = (x + dx, y + dy)
            if n in passable and n not in seen:
                seen.add(n)
                q.append(n)
    for pos, c in passable.items():
        if pos not in seen:
            c.passable = False
            c.tile = "wall"


def gen_cells(li, rnd, story=0, story_rnd=None, size=SIZE):
    """Клетки одной локации li со спавном в центре. Возвращает (batch, story).

    `rnd` задаёт рельеф, `story_rnd` (если передан) — тексты клеток: разные
    сиды правят разные стороны мира независимо друг от друга. `size` —
    сторона квадратной сетки (10 по умолчанию).
    """
    batch = []
    cx, cy = size // 2, size // 2
    for x in range(size):
        for y in range(size):
            border = x in (0, size - 1) or y in (0, size - 1)
            wall = border or (rnd.random() < 0.15 and (x, y) != (cx, cy))
            if story_rnd is not None:
                name, desc, tile = story_rnd.choice(data.STORIES)
            else:
                name, desc, tile = data.STORIES[story % len(data.STORIES)]
            story += 1
            batch.append(Cell(loc=li, x=x, y=y, name=name, desc=desc,
                              tile="wall" if wall else tile, passable=not wall))
    _connect(batch, (cx, cy))
    return batch, story


def is_castle(locs, li):
    """Угловой замок: безопасная локация с именем «Замок …» и размером 25×25."""
    try:
        return bool(locs[li][2] == "safe" and str(locs[li][0]).startswith("Замок"))
    except (IndexError, TypeError):
        return False


def gen_castle_cells(li, rnd, size=25, story_rnd=None):
    """Клетки углового замка 25×25: в четырёх углах — замки 10×10
    с жителями, между ними — опасные пустоши с мобами.

    Разбивка 25 = 10 + 5 + 10: угловые кварталы 10×10 — замки (village,
    безопасно, там NPC), крест шириной 5 между ними — пустоши и дороги
    (твари), в центре — площадь. Дороги образуют решётку (ряды и колонны
    10/12/14), поэтому из каждого замка есть путь к центру, а двери на
    границах — одна в середине, как у обычных локаций: бесшовные
    переходы работают для любого размера.
    """
    batch = []
    cx, cy = size // 2, size // 2          # 12, 12
    s = size
    b = s // 2 - 3                         # 9: последний ряд углового квартала
    blocks = [((0, b), (0, b)),            # северо-западный замок 10×10
              ((0, b), (s - b - 1, s - 1)),   # северо-восточный
              ((s - b - 1, s - 1), (0, b)),   # юго-западный
              ((s - b - 1, s - 1), (s - b - 1, s - 1))]  # юго-восточный

    def in_block(x, y):
        return any(x0 <= x <= x1 and y0 <= y <= y1
                   for (x0, x1), (y0, y1) in blocks)

    for x in range(s):
        for y in range(s):
            if in_block(x, y):
                wall, tile = False, "village"
                name, desc = "Замок", "Каменные стены замка. Здесь безопасно."
            elif abs(x - cx) <= 2 and abs(y - cy) <= 2:
                wall, tile = False, "grass"
                name, desc = "Центральная площадь", "Площадь с патрулями."
            elif x in (0, s - 1) or y in (0, s - 1):
                is_door = ((x == cx and y in (0, s - 1)) or
                           (y == cy and x in (0, s - 1)))
                wall = not is_door
                tile = "wall" if wall else "road"
                name = "Ворота" if is_door else "Стена"
                desc = "Ворота замка." if is_door else "Глухая стена."
            else:
                wall = rnd.random() < 0.3
                tile = "wall" if wall else "grass"
                name = "Пустошь"
                desc = ("Опасная земля между замками." if not wall
                        else "Скала.")
            batch.append(Cell(loc=li, x=x, y=y, name=name, desc=desc,
                              tile=tile, passable=not wall))

    def open_(x, y):
        c = next((c for c in batch if c.x == x and c.y == y), None)
        if c and not c.passable:
            c.passable = True
            c.tile = "road"
            c.name, c.desc = "Тракт", "Утоптанная дорога между замками."

    # Решётка дорог: ряды и колонны 10, 12, 14 — от ворот к воротам.
    # Каждый замок 10×10 примыкает к дороге своей стороной.
    for row in (b + 1, cx, b + 3):
        for y in range(1, s - 1):
            open_(row, y)
    for col in (b + 1, cy, b + 3):
        for x in range(1, s - 1):
            open_(x, col)
    # Площадь остаётся площадью, а не перекрёстком дорог.
    for x in range(cx - 2, cx + 3):
        for y in range(cy - 2, cy + 3):
            c = next(c for c in batch if c.x == x and c.y == y)
            c.tile = "grass"
            c.passable = True
            c.name, c.desc = "Центральная площадь", "Площадь с патрулями."
    _connect(batch, (cx, cy))
    return batch, 0


def generate(seed=1337, locations=None, grid=None, seeds=None, floors=None,
             sizes=None):
    """Возвращает {key: Cell}. `grid` — {str(loc): [wx, wy]} на мировой сетке;
    если не задан, локации связываются цепочкой, как раньше.

    `seeds` — словарь частных сидов (см. SEEDS). Без него всё выводится из
    одного `seed`, как и раньше. `sizes` — {loc: размер сетки} для локаций,
    чей размер отличается от стандартного (угловые замки 25×25).
    """
    locs = locations if locations is not None else data.LOCATIONS
    seeds = seeds or seeds_of({"seed": seed})
    rnd = random.Random(seeds.get("terrain", seed))
    story_rnd = random.Random(seeds.get("stories", seed))
    cells, story = {}, 0
    floors = floors or {}
    sizes = sizes or {}
    for li in range(len(locs)):
        size = _size_of(sizes, li)
        count = max(1, int(floors.get(str(li), floors.get(li, 1)) or 1))
        for floor in range(count):
            batch, story = (gen_castle_cells(li, rnd, size, story_rnd)
                            if is_castle(locs, li) else
                            gen_cells(li, rnd, story, story_rnd, size))
            for c in batch:
                c.floor = floor
                cells[c.key] = c
        # Лестницы ставятся на двух соседних проходимых клетках и ведут
        # в соседний этаж. Они симметричны и всегда доступны с обеих сторон.
        for floor in range(count - 1):
            # На промежуточном этаже лестница вверх и вниз стоят на
            # соседних клетках: обе стороны перехода остаются доступны.
            stair_y = size // 2 + floor
            a = (cells.get(f"{li}:{size // 2}:{stair_y}") if floor == 0 else
                 cells.get(f"{li}:{floor}:{size // 2}:{stair_y}"))
            b = cells.get(f"{li}:{floor + 1}:{size // 2}:{stair_y}")
            if a is None or b is None:
                continue
            a.link = (li, size // 2, stair_y, floor + 1)
            b.link = (li, size // 2, stair_y, floor)
            a.name = "Лестница вниз"
            b.name = "Лестница вверх"
            a.desc = "Каменная лестница ведёт ниже."
            b.desc = "Лестница ведёт наверх."
            a.tile = b.tile = "road"
    if grid:
        _link_by_grid(cells, grid, sizes)
    else:
        for a in range(len(locs) - 1):
            _link_east(cells, a, a + 1, sizes)
    _populate(cells, rnd, locs, seeds, sizes)
    return cells


# ── швы между локациями ───────────────────────────────────

def _road(c, link):
    c.passable = True
    c.tile = "road"
    c.name = "Тракт между землями"
    c.desc = "Утоптанная дорога уходит вдаль."
    c.link = link


def _size_of(sizes, li, default=SIZE):
    if not sizes:
        return default
    return max(3, int(sizes.get(li, sizes.get(str(li), default)) or default))


def _carve_road(cells, li, size, row, col_from, col_to):
    """Прорубить дорогу вдоль ряда `row` от col_from до col_to (включительно)."""
    for y in range(min(col_from, col_to), max(col_from, col_to) + 1):
        c = cells.get(f"{li}:{row}:{y}")
        if c and not c.passable:
            _road(c, c.link)


def _carve_road_col(cells, li, size, col, row_from, row_to):
    """Прорубить дорогу вдоль колонны `col` от row_from до row_to (включительно)."""
    for x in range(min(row_from, row_to), max(row_from, row_to) + 1):
        c = cells.get(f"{li}:{x}:{col}")
        if c and not c.passable:
            _road(c, c.link)


def _link_east(cells, a, b, sizes=None):
    """Восточная граница A ↔ западная граница B — одна дверь в центре, а не стена.

    Дорога от центра к воротам идёт ВДОЛЬ ряда ворот (x = mid): раньше
    здесь прорубали колонну, и дверь на восточной границе оставалась
    за стеной — перейти было некуда.
    """
    sa, sb = _size_of(sizes, a), _size_of(sizes, b)
    mid_a, mid_b = sa // 2, sb // 2
    _road(cells[f"{a}:{mid_a}:{sa - 1}"], (b, mid_b, 1))
    _road(cells[f"{b}:{mid_b}:0"], (a, mid_a, sa - 2))
    # дорога от центра к двери — тот же ряд, что и ворота
    _carve_road(cells, a, sa, mid_a, 1, sa - 2)
    _carve_road(cells, b, sb, mid_b, 1, sb - 2)


def _link_south(cells, a, b, sizes=None):
    """Южная граница A ↔ северная граница B — одна дверь в центре.

    Дорога от центра к воротам идёт ВДОЛЬ колонны ворот (y = mid) — до
    исправления прорубали ряд, и южные ворота упирались в стену.
    """
    sa, sb = _size_of(sizes, a), _size_of(sizes, b)
    mid_a, mid_b = sa // 2, sb // 2
    _road(cells[f"{a}:{sa - 1}:{mid_a}"], (b, 1, mid_b))
    _road(cells[f"{b}:0:{mid_b}"], (a, sa - 2, mid_a))
    _carve_road_col(cells, a, sa, mid_a, 1, sa - 2)
    _carve_road_col(cells, b, sb, mid_b, 1, sb - 2)


def _link_by_grid(cells, grid, sizes=None):
    """Швы по соседству на мировой сетке: восток/запад и север/юг."""
    pos = {int(k): tuple(v) for k, v in grid.items()}
    pairs = set()
    for ai, (ax, ay) in pos.items():
        for bi, (bx, by) in pos.items():
            if ai == bi or (bi, ai) in pairs:
                continue
            if (bx, by) == (ax + 1, ay):
                _link_east(cells, ai, bi, sizes)
                pairs.add((ai, bi))
            elif (bx, by) == (ax, ay + 1):
                _link_south(cells, ai, bi, sizes)
                pairs.add((ai, bi))


def link_new_location(cells, li, grid, sizes=None):
    """Вшить свежедобавленную локацию li в существующий мир.

    Граница связывается только если обе стороны свободны (ничьих швов ещё
    нет) — чужие рукоправные переходы не затираются. Возвращает отчёт.
    `sizes` — {loc: размер сетки} (угловые замки 25×25).
    """
    pos = {int(k): tuple(v) for k, v in grid.items()}
    if li not in pos:
        return ["Локация не размещена на сетке мира."]
    ax, ay = pos[li]
    report = []
    dirs = {"восток": (1, 0, "e"), "запад": (-1, 0, "w"),
            "юг": (0, 1, "s"), "север": (0, -1, "n")}
    loc_name = data.LOCATIONS[li][0] if li < len(data.LOCATIONS) else str(li)
    sa = _size_of(sizes, li)
    mid_a = sa // 2
    for name, (dx, dy, side) in dirs.items():
        nb = next((j for j, (x, y) in pos.items() if (x, y) == (ax + dx, ay + dy)), None)
        if nb is None:
            continue
        sb = _size_of(sizes, nb)
        mid_b = sb // 2
        if side == "e":
            mine, theirs = [(li, mid_a, sa - 1)], [(nb, mid_b, 0)]
        elif side == "w":
            mine, theirs = [(li, mid_a, 0)], [(nb, mid_b, sb - 1)]
        elif side == "s":
            mine, theirs = [(li, sa - 1, mid_a)], [(nb, 0, mid_b)]
        else:
            mine, theirs = [(li, 0, mid_a)], [(nb, sb - 1, mid_b)]
        busy = any(cells.get(f"{l}:{x}:{y}") and cells[f"{l}:{x}:{y}"].link
                   for l, x, y in mine + theirs)
        if busy:
            report.append(f"{name}: граница с «{data.LOCATIONS[nb][0]}» уже занята швом.")
            continue
        if side == "e":
            _link_east(cells, li, nb, sizes)
        elif side == "w":
            _link_east(cells, nb, li, sizes)
        elif side == "s":
            _link_south(cells, li, nb, sizes)
        else:
            _link_south(cells, nb, li, sizes)
        report.append(f"🔗 {name} ↔ {data.LOCATIONS[nb][0]} (1 дверь)")
    if not report:
        report.append(f"Соседей у «{loc_name}» на сетке нет.")
    return report


# ── заселение ─────────────────────────────────────────────

def _populate(cells, rnd, locs=None, seeds=None, sizes=None):
    """Расставить NPC, мобов и сундуки по типам локаций.

    У жителей, тварей и сундуков свои сиды: можно перетряхнуть добычу,
    не трогая рельеф и расстановку мобов. Заказчики заданий живут в
    деревне, остальные жители — по угловым замкам.
    """
    locs = locs if locs is not None else data.LOCATIONS
    seeds = seeds or {}
    sizes = sizes or {}
    npc_rnd = random.Random(seeds.get("npc")) if seeds.get("npc") else rnd
    mob_rnd = random.Random(seeds.get("mobs")) if seeds.get("mobs") else rnd
    chest_rnd = random.Random(seeds.get("chests")) if seeds.get("chests") else rnd

    def center(li):
        s = _size_of(sizes, li)
        return (s // 2, s // 2)

    def free(li):
        cx, cy = center(li)
        return [c for c in cells.values()
                if c.loc == li and c.passable and not c.link
                and (c.x, c.y) != (cx, cy) and c.mob < 0 and c.npc < 0]

    # NPC — по безопасным локациям: деревня держит заказчиков заданий,
    # кузнеца, лекаря и картографа (первые шесть жителей), остальные —
    # «странствующие» — расходятся по угловым замкам (по два-три на замок).
    safe_locs = [i for i, l in enumerate(locs) if l[2] == "safe"] or [0]
    npc_list = list(data.NPCS)
    village = safe_locs[0]
    spots = free(village)
    npc_rnd.shuffle(spots)
    for i in range(min(6, len(npc_list), len(spots))):
        spots[i].npc = i
    rest = npc_list[6:]
    castles = [i for i in safe_locs if i != village and is_castle(locs, i)]
    if castles:
        for n in range(len(rest)):
            castle = castles[n % len(castles)]
            spot = [c for c in free(castle) if c.tile == "village"]
            if not spot:
                spot = free(castle)
            if not spot:
                continue
            npc_rnd.shuffle(spot)
            spot[0].npc = n + 6
    elif rest:
        spots = free(village)
        npc_rnd.shuffle(spots)
        for i in range(min(len(rest), len(spots))):
            spots[i].npc = i + 6

    # Мобы — в своих локациях; если локация удалена/не создана, моб не спавнится.
    # В угловых замках твари живут в пустошах между замками 10×10, а не
    # внутри цитаделей.
    def mob_spots(li):
        if is_castle(locs, li):
            return [c for c in free(li) if c.tile != "village"]
        return free(li)

    for mi, m in enumerate(data.MOBS):
        li = m[8]
        if li >= len(locs):
            continue
        count = 1 if m[0] == "Пожиратель Глубин" else 4
        spots = mob_spots(li)
        mob_rnd.shuffle(spots)
        for c in spots[:count]:
            c.mob = mi

    # Сундуки — во всех опасных локациях (dangerous/dungeon/boss)
    for li, l in enumerate(locs):
        if l[2] in ("dangerous", "dungeon", "boss"):
            spots = free(li)
            chest_rnd.shuffle(spots)
            for c in spots[:5]:
                c.chest = True


def cell_at(cells, loc, x, y, floor=0):
    key = f"{loc}:{x}:{y}" if not floor else f"{loc}:{floor}:{x}:{y}"
    return cells.get(key)


def neighbours(cells, loc, x, y, floor=0):
    """{направление: проходимо?} для 8 сторон."""
    out = {}
    for d, (dx, dy) in DIRS.items():
        c = cell_at(cells, loc, x + dx, y + dy, floor)
        out[d] = bool(c and c.passable)
    return out


DIRS = {
    "nw": (-1, -1), "n": (-1, 0), "ne": (-1, 1),
    "w": (0, -1), "e": (0, 1),
    "sw": (1, -1), "s": (1, 0), "se": (1, 1),
}

ARROWS = {"nw": "↖️", "n": "⬆️", "ne": "↗️", "w": "⬅️", "e": "➡️",
          "sw": "↙️", "s": "⬇️", "se": "↘️"}

files.engine/party.py:
"""Отряды: повод звать друзей.

До этого играть вместе было нельзя — взаимодействие исчерпывалось аукционом
и таблицей топа. Отряд до `MAX_SIZE` героев даёт общую добычу и делает
подземелья и боссов осмысленными.

Как устроено. Отряд — запись в настройках (общая для бота и панели):
`{"id", "leader", "members": [tg_id], "created"}`. Игрок состоит максимум
в одном. Приглашение кладётся приглашённому в `p.party_invite` и ждёт
ответа — навязать участие нельзя.

Делёж награды. Опыт и золото за победу получают все, кто **в той же
локации** (иначе можно было бы «возить» друга по миру, стоя в городе).
Каждому достаётся полная доля плюс бонус за игру вместе — но общий фонд
ограничен `MAX_TOTAL`, чтобы отряд не превращался в станок по печати денег.
"""
import time

from engine.models import Reply

PARTIES = "parties"
MAX_SIZE = 3                 # больше — уже толпа, бой станет нечитаемым
TOGETHER_BONUS = 0.15        # +15% каждому за игру в отряде
MAX_TOTAL = 2.0              # суммарно отряд не получит больше, чем ×2


# ── хранилище ───────────────────────────────────────────────

def _all(store):
    lst = store.settings.get(PARTIES)
    if not isinstance(lst, list):
        lst = []
        store.settings[PARTIES] = lst
    return lst


def of(store, p):
    """Отряд игрока или None."""
    for party in _all(store):
        if int(p.tg_id) in [int(m) for m in party.get("members", [])]:
            return party
    return None


def members(store, p, same_loc=None):
    """Соратники игрока (без него самого). `same_loc` — только рядом."""
    party = of(store, p)
    if not party:
        return []
    out = []
    for tg_id in party.get("members", []):
        if int(tg_id) == int(p.tg_id):
            continue
        q = store.players.get(int(tg_id))
        if q is None or not q.created_char:
            continue
        if same_loc is not None and q.loc != same_loc:
            continue
        out.append(q)
    return out


def is_leader(store, p):
    party = of(store, p)
    return bool(party and int(party.get("leader", 0)) == int(p.tg_id))


# ── создание и приглашения ──────────────────────────────────

def create(store, p):
    if of(store, p):
        return Reply(alert="Ты уже в отряде.")
    party = {"id": int(time.time() * 1000) % 10_000_000,
             "leader": int(p.tg_id), "members": [int(p.tg_id)],
             "created": int(time.time())}
    _all(store).append(party)
    store.save()
    return card(store, p)


def invite(store, p, name_or_id):
    """Позвать героя по имени или Telegram ID."""
    party = of(store, p) or None
    if party is None:
        create(store, p)
        party = of(store, p)
    if int(party.get("leader", 0)) != int(p.tg_id):
        return Reply(alert="Звать в отряд может только предводитель.")
    if len(party.get("members", [])) >= MAX_SIZE:
        return Reply(alert=f"В отряде уже {MAX_SIZE} героя — больше некуда.")

    target = _find(store, name_or_id)
    if target is None:
        return Reply(alert="Такого героя нет.")
    if int(target.tg_id) == int(p.tg_id):
        return Reply(alert="Себя звать не нужно.")
    if of(store, target):
        return Reply(alert=f"{target.name} уже в отряде.")

    target.party_invite = int(party["id"])
    store.save_player(target)
    _tell(store, target.tg_id,
          f"🤝 <b>{p.name}</b> зовёт тебя в отряд!\n"
          f"Открой «🤝 Отряд» в меню, чтобы принять или отказаться.")
    return Reply(text=f"📨 Приглашение отправлено: <b>{target.name}</b>.",
                 keyboard=[[("🤝 Отряд", "party")], [("◀️ В мир", "world")]])


def _find(store, needle):
    needle = str(needle).strip().lower()
    if not needle:
        return None
    for q in store.players.values():
        if not q.created_char:
            continue
        if str(q.tg_id) == needle or q.name.lower() == needle:
            return q
    for q in store.players.values():          # частичное совпадение имени
        if q.created_char and needle in q.name.lower():
            return q
    return None


def accept(store, p):
    pid = int(getattr(p, "party_invite", 0) or 0)
    if not pid:
        return Reply(alert="Тебя никто не звал.")
    party = next((x for x in _all(store) if int(x["id"]) == pid), None)
    p.party_invite = 0
    if party is None:
        store.save_player(p)
        return Reply(alert="Этот отряд уже распался.")
    if len(party["members"]) >= MAX_SIZE:
        store.save_player(p)
        return Reply(alert="Отряд уже полон.")
    party["members"].append(int(p.tg_id))
    store.save_player(p)
    for q in members(store, p):
        _tell(store, q.tg_id, f"🤝 <b>{p.name}</b> присоединился к отряду!")
    return card(store, p)


def decline(store, p):
    p.party_invite = 0
    store.save_player(p)
    return Reply(text="Ты отклонил приглашение.",
                 keyboard=[[("◀️ В мир", "world")]])


def leave(store, p):
    party = of(store, p)
    if not party:
        return Reply(alert="Ты не в отряде.")
    party["members"] = [m for m in party["members"] if int(m) != int(p.tg_id)]
    leader_left = int(party.get("leader", 0)) == int(p.tg_id)
    if len(party["members"]) < 2:             # отряд из одного смысла не имеет
        for tg_id in party["members"]:
            _tell(store, tg_id, "🤝 Отряд распался.")
        _all(store)[:] = [x for x in _all(store) if x is not party]
    elif leader_left:
        party["leader"] = int(party["members"][0])
        _tell(store, party["leader"], "🤝 Теперь ты ведёшь отряд.")
    store.save()
    return Reply(text="🚪 Ты покинул отряд.",
                 keyboard=[[("🤝 Отряд", "party")], [("◀️ В мир", "world")]])


# ── общая награда ───────────────────────────────────────────

def share(store, p, gold, exp):
    """Раздать соратникам в той же локации их долю. Возвращает строки отчёта.

    Долю получает каждый, кто рядом; фонд ограничен MAX_TOTAL, поэтому
    большой отряд не выгоднее маленького сверх меры.
    """
    from engine import rules

    mates = members(store, p, same_loc=p.loc)
    if not mates:
        return []
    part = _fund(len(mates) + 1) / (len(mates) + 1)
    lines = []
    for q in mates:
        q_gold = max(1, int(gold * part))
        q_exp = max(1, int(exp * part))
        q.gold += q_gold
        levels = rules.add_exp(q, q_exp)
        store.save_player(q)
        _tell(store, q.tg_id,
              f"🤝 {p.name} бьётся рядом: +{q_gold} 🪙 +{q_exp} ⭐"
              + (f"\n🎖 Новый уровень: {q.level}!" if levels else ""))
        lines.append(f"🤝 {q.name}: +{q_gold} 🪙 +{q_exp} ⭐")
    return lines


def _fund(size):
    """Общий фонд награды на отряд из `size` героев, стоящих вместе."""
    if size < 2:
        return 1.0                        # один в поле — обычная награда
    return min(MAX_TOTAL, 1.0 + TOGETHER_BONUS * size)


def bonus(store, p):
    """Множитель награды самого игрока: его доля из общего фонда."""
    mates = members(store, p, same_loc=p.loc)
    if not mates:
        return 1.0                        # соратников рядом нет — как обычно
    size = len(mates) + 1
    return _fund(size) / size


# ── экраны ──────────────────────────────────────────────────

def card(store, p):
    """Экран отряда: состав, приглашение, выход."""
    pending = int(getattr(p, "party_invite", 0) or 0)
    if pending:
        party = next((x for x in _all(store) if int(x["id"]) == pending), None)
        who = store.players.get(int(party["leader"])) if party else None
        name = who.name if who else "Кто-то"
        return Reply(text=f"🤝 <b>Приглашение в отряд</b>\n\n<b>{name}</b> зовёт "
                          f"тебя в свой отряд.\n\n<i>Вместе добыча щедрее: "
                          f"+{int(TOGETHER_BONUS * 100)}% каждому, кто рядом.</i>",
                     keyboard=[[("✅ Принять", "pjoin"), ("❌ Отказаться", "pno")],
                               [("◀️ В мир", "world")]])

    party = of(store, p)
    if not party:
        return Reply(text=(
            "🤝 <b>Отряд</b>\n\nТы странствуешь в одиночку.\n\n"
            f"<i>В отряде до {MAX_SIZE} героев. Опыт и золото получают все, "
            f"кто в одной локации, и каждому идёт бонус "
            f"+{int(TOGETHER_BONUS * 100)}%.</i>\n\n"
            "Чтобы позвать: <code>/invite Имя</code> — или кнопкой ниже."),
            keyboard=[[("➕ Создать отряд", "pnew")], [("◀️ В мир", "world")]])

    lines = ["🤝 <b>Отряд</b>\n"]
    for tg_id in party["members"]:
        q = store.players.get(int(tg_id))
        if q is None:
            continue
        crown = "👑 " if int(party["leader"]) == int(tg_id) else "▫️ "
        near = "рядом" if q.loc == p.loc else "далеко"
        you = " (ты)" if int(tg_id) == int(p.tg_id) else ""
        lines.append(f"{crown}<b>{q.name}</b>{you} — ур. {q.level} · {near}")
    mates = members(store, p, same_loc=p.loc)
    if mates:
        lines.append(f"\n✨ Вместе: награда ×{_fund(len(mates) + 1):.2f} на отряд "
                     f"(каждому по {bonus(store, p) * 100:.0f}% от обычной)")
    else:
        lines.append("\n<i>Соратники в других краях — доли не будет, "
                     "пока не соберётесь вместе.</i>")

    rows = []
    if is_leader(store, p) and len(party["members"]) < MAX_SIZE:
        rows.append([("📨 Позвать: /invite Имя", "pnoop")])
    rows.append([("🚪 Покинуть отряд", "pleave")])
    rows.append([("◀️ В мир", "world")])
    return Reply(text="\n".join(lines), keyboard=rows)


def _tell(store, tg_id, text):
    """Весть соратнику через общую очередь исходящих."""
    from engine import adminops
    adminops.queue(store, int(tg_id), text)

files.engine/respawn.py:
"""Восстановление мира: твари и сундуки возвращаются со временем.

Без этого мир одноразовый: убитая тварь исчезала навсегда, вскрытый сундук
не появлялся снова, и через вечер игры карта пустела насовсем.

Как устроено. Убийство не стирает тварь молча, а ставит на клетку метку
`mob_at` — время возвращения. `tick()` вызывается на шаге игрока (там же,
где `cataclysm.auto`), поэтому фоновые задачи не нужны: мир оживает ровно
тогда, когда в него кто-то смотрит.

Сундук возвращается не на своё место, а на случайную клетку локации: иначе
игроки заучили бы точки и ходили по кругу.
"""
import random
import time

from engine import data
from engine import world as W

# Сколько ждать возвращения, в минутах, по типу локации.
MOB_DELAY = {"safe": 0, "dangerous": 15, "dungeon": 30, "boss": 45}
CHEST_DELAY = {"safe": 0, "dangerous": 25, "dungeon": 40, "boss": 60}

SETTING_MOB = "respawn_mob_min"      # переопределение из панели
SETTING_CHEST = "respawn_chest_min"
SETTING_ON = "respawn_enabled"


def enabled(store):
    return bool(store.settings.get(SETTING_ON, True))


def _loc_type(loc):
    return data.LOCATIONS[loc][2] if 0 <= loc < len(data.LOCATIONS) else "dangerous"


def _minutes(store, kind, loc):
    """Задержка для локации: настройка панели или значение по типу."""
    table = MOB_DELAY if kind == "mob" else CHEST_DELAY
    key = SETTING_MOB if kind == "mob" else SETTING_CHEST
    override = (store.settings.get(key) or {}).get(_loc_type(loc))
    if override is None:
        return table.get(_loc_type(loc), 15)
    try:
        return max(0, float(override))
    except (TypeError, ValueError):
        return table.get(_loc_type(loc), 15)


# ── постановка в очередь ────────────────────────────────────

def schedule_mob(store, cell):
    """Тварь убита: наметить возвращение. В безопасных землях — никогда."""
    cell.mob = -1
    delay = _minutes(store, "mob", cell.loc)
    cell.mob_at = (time.time() + delay * 60) if delay > 0 else 0.0


def schedule_chest(store, cell):
    """Сундук вскрыт: наметить появление нового где-то в этой локации."""
    cell.chest = False
    delay = _minutes(store, "chest", cell.loc)
    cell.chest_at = (time.time() + delay * 60) if delay > 0 else 0.0


# ── возвращение ─────────────────────────────────────────────

def tick(store, rng=None):
    """Вернуть всё, чей срок вышел. Возвращает (тварей, сундуков).

    Клетки под игроками пропускаем: тварь не должна возникать прямо под
    ногами, а сундук — появляться в занятой клетке.
    """
    if not enabled(store):
        return 0, 0
    rng = rng or random
    now = time.time()
    busy = {f"{p.loc}:{p.x}:{p.y}" for p in store.players.values()}
    mobs = chests = 0

    for c in store.world.values():
        if c.mob_at and now >= c.mob_at:
            if c.key in busy or not c.passable or c.mob >= 0 or c.npc >= 0:
                c.mob_at = now + 60          # занято — заглянем через минуту
                continue
            c.mob = _pick_mob(c.loc, rng)
            c.mob_at = 0.0
            mobs += 1

    # Сундуки: метка висит на вскрытой клетке, а сокровище кладём в другую.
    for c in list(store.world.values()):
        if not c.chest_at or now < c.chest_at:
            continue
        c.chest_at = 0.0
        spot = _free_spot(store, c.loc, busy, rng)
        if spot is not None:
            spot.chest = True
            chests += 1
    if mobs or chests:
        store.save()
    return mobs, chests


def _pick_mob(loc, rng):
    """Тварь под стать локации: свои по прописке, иначе по её уровню."""
    own = [i for i, m in enumerate(data.MOBS) if m[8] == loc]
    if own:
        return rng.choice(own)
    lvl = data.LOCATIONS[loc][3] if loc < len(data.LOCATIONS) else 1
    fit = [i for i, m in enumerate(data.MOBS) if m[2] <= max(1, lvl) + 2]
    return rng.choice(fit or range(len(data.MOBS)))


def _free_spot(store, loc, busy, rng):
    """Случайная свободная клетка локации под новый сундук."""
    free = [c for c in store.world.values()
            if c.loc == loc and c.passable and not c.link and not c.chest
            and c.mob < 0 and c.npc < 0 and c.key not in busy
            and (c.x, c.y) != W.SPAWN]
    return rng.choice(free) if free else None


# ── сводка для панели ───────────────────────────────────────

def pending(store, loc=None):
    """Что сейчас в очереди на возвращение: [(клетка, вид, секунд)]."""
    now = time.time()
    out = []
    for c in store.world.values():
        if loc is not None and c.loc != int(loc):
            continue
        if c.mob_at:
            out.append((c, "mob", max(0, int(c.mob_at - now))))
        if c.chest_at:
            out.append((c, "chest", max(0, int(c.chest_at - now))))
    return sorted(out, key=lambda r: r[2])


def delays(store):
    """Текущие задержки по типам локаций — для формы настроек."""
    out = {}
    for kind, table in (("mob", MOB_DELAY), ("chest", CHEST_DELAY)):
        out[kind] = {t: _minutes(store, kind, _first_loc_of(t))
                     for t in table}
    return out


def _first_loc_of(loc_type):
    """Индекс любой локации нужного типа — чтобы прочитать её задержку."""
    for i, l in enumerate(data.LOCATIONS):
        if l[2] == loc_type:
            return i
    return 0


def set_delays(store, kind, values):
    """Сохранить задержки по типам локаций (минуты)."""
    key = SETTING_MOB if kind == "mob" else SETTING_CHEST
    saved = store.settings.setdefault(key, {})
    for loc_type, raw in values.items():
        try:
            saved[loc_type] = max(0, float(raw))
        except (TypeError, ValueError):
            continue
    store.save()
    return saved

files.engine/quests.py:
"""Задания: цель для игрока и повод вернуться завтра.

Три вида, и все проверяются по тому, что в игре уже считается:
  hunt    — убить тварей вида (счётчик ведём при победе в бою);
  reach   — дойти до локации (сверяем с `p.visited`, туман войны уже есть);
  deliver — принести предмет заказчику (смотрим в сумке).

Состояние живёт в `p.quests`: {id задания: {"n": прогресс, "done": сдано}}.
Ежедневные сбрасываются раз в сутки по `p.quest_day`.
"""
import time

from engine import data, factions, items, rules
from engine.models import Reply

HUNT, REACH, DELIVER = "hunt", "reach", "deliver"
DAILY_LIMIT = 2                 # сколько ежедневных доступно за раз


def _row(qid):
    for q in data.QUESTS:
        if q[0] == int(qid):
            return q
    return None


def fields(q):
    """Кортеж задания -> словарь, чтобы не помнить порядок полей."""
    return dict(id=q[0], name=q[1], text=q[2], npc=q[3], kind=q[4],
                target=q[5], need=q[6], gold=q[7], exp=q[8], item=q[9],
                level=q[10], daily=q[11])


def state(p):
    st = getattr(p, "quests", None)
    if not isinstance(st, dict):
        st = {}
        p.quests = st
    return st


# ── ежедневный сброс ────────────────────────────────────────

def _today():
    return time.strftime("%Y-%m-%d")


def refresh_daily(p):
    """Раз в сутки снимает отметки с ежедневных заданий. True, если сбросили."""
    if getattr(p, "quest_day", "") == _today():
        return False
    st = state(p)
    for q in data.QUESTS:
        if q[11]:
            st.pop(str(q[0]), None)
    p.quest_day = _today()
    return True


# ── доступность ─────────────────────────────────────────────

def taken(p, qid):
    return str(qid) in state(p)


def done(p, qid):
    return bool(state(p).get(str(qid), {}).get("done"))


def available(p, npc_index=None):
    """Задания, которые игрок может взять у этого NPC (или вообще)."""
    refresh_daily(p)
    out = []
    dailies = 0
    for q in data.QUESTS:
        f = fields(q)
        if npc_index is not None and f["npc"] != int(npc_index):
            continue
        if p.level < f["level"] or taken(p, f["id"]):
            continue
        if f["daily"]:
            dailies += 1
            if dailies > DAILY_LIMIT:
                continue
        out.append(q)
    return out


def active(p):
    """Взятые и ещё не сданные."""
    refresh_daily(p)
    st = state(p)
    return [q for q in data.QUESTS
            if str(q[0]) in st and not st[str(q[0])].get("done")]


def take(p, qid):
    q = _row(qid)
    if q is None:
        return Reply(alert="Такого задания нет.")
    f = fields(q)
    if p.level < f["level"]:
        return Reply(alert=f"Нужен {f['level']} уровень.")
    if taken(p, qid):
        return Reply(alert="Это задание уже у тебя.")
    state(p)[str(qid)] = {"n": 0, "done": False}
    if f["kind"] == REACH and _reached(p, f["target"]):
        state(p)[str(qid)]["n"] = f["need"]      # уже бывал там
    return Reply(text=f"📜 <b>Задание принято</b>\n\n<b>{f['name']}</b>\n"
                      f"<i>{f['text']}</i>\n\n{goal_line(p, q)}",
                 keyboard=[[("📜 Мои задания", "quests")], [("◀️ В мир", "world")]])


def abandon(p, qid):
    if not taken(p, qid):
        return Reply(alert="Ты за это не брался.")
    state(p).pop(str(qid), None)
    return Reply(text="🚮 Задание отброшено.", keyboard=[[("📜 Задания", "quests")]])


# ── прогресс ────────────────────────────────────────────────

def _reached(p, loc):
    return any(k.startswith(f"{int(loc)}:") for k in (getattr(p, "visited", []) or []))


def on_kill(p, mob_index):
    """Победа над тварью двигает охотничьи задания. Возвращает готовые."""
    ready = []
    for q in active(p):
        f = fields(q)
        if f["kind"] != HUNT:
            continue
        if f["target"] not in (-1, int(mob_index)):
            continue
        rec = state(p)[str(f["id"])]
        rec["n"] = min(f["need"], rec.get("n", 0) + 1)
        if rec["n"] >= f["need"]:
            ready.append(q)
    return ready


def on_enter(p, loc):
    """Приход в локацию закрывает разведку."""
    ready = []
    for q in active(p):
        f = fields(q)
        if f["kind"] == REACH and int(f["target"]) == int(loc):
            rec = state(p)[str(f["id"])]
            rec["n"] = f["need"]
            ready.append(q)
    return ready


def progress(p, q):
    """Сколько сделано из нужного."""
    f = fields(q)
    if f["kind"] == DELIVER:
        have = sum(1 for i in p.inventory if int(i) == int(f["target"]))
        return min(have, f["need"]), f["need"]
    rec = state(p).get(str(f["id"]), {})
    return min(rec.get("n", 0), f["need"]), f["need"]


def complete(p, q):
    n, need = progress(p, q)
    return n >= need


def goal_line(p, q):
    """Человеческая строка цели с прогрессом."""
    f = fields(q)
    n, need = progress(p, q)
    if f["kind"] == HUNT:
        who = data.MOBS[f["target"]][0] if f["target"] >= 0 else "любые твари"
        what = f"⚔️ {who}: {n}/{need}"
    elif f["kind"] == REACH:
        where = (data.LOCATIONS[f["target"]][0]
                 if f["target"] < len(data.LOCATIONS) else "?")
        what = f"🧭 Дойти: {where} — {'да' if n >= need else 'ещё нет'}"
    else:
        it = rules.item(f["target"])
        what = f"🎒 {it['icon']} {it['name']}: {n}/{need}"
    prize = f"🪙 {f['gold']} · ⭐ {f['exp']}"
    if f["item"] >= 0:
        it = rules.item(f["item"])
        prize += f" · {it['icon']} {it['name']}"
    return f"{what}\n🎁 Награда: {prize}"


# ── сдача ───────────────────────────────────────────────────

def hand_in(store, p, qid):
    q = _row(qid)
    if q is None or not taken(p, qid):
        return Reply(alert="Это задание не у тебя.")
    if done(p, qid):
        return Reply(alert="Уже сдано.")
    f = fields(q)
    if not complete(p, q):
        return Reply(alert="Задание ещё не выполнено.")

    if f["kind"] == DELIVER:                 # предмет уходит заказчику
        for _ in range(f["need"]):
            if int(f["target"]) in p.inventory:
                p.inventory.remove(int(f["target"]))

    p.gold += f["gold"]
    levels = rules.add_exp(p, f["exp"])
    lines = [f"✅ <b>{f['name']}</b> — выполнено!",
             f"🪙 +{f['gold']}   ⭐ +{f['exp']}"]
    if f["item"] >= 0:
        p.inventory.append(int(f["item"]))
        inst = items.create(store, int(f["item"]), source="quest",
                            owner=p.tg_id, luck=p.luck, detail=f["name"])
        if inst is not None:
            lines.append(f"📜 Награда: {inst['icon']} <b>{items.title(inst)}</b>")
        else:
            it = rules.item(f["item"])
            lines.append(f"📜 Награда: {it['icon']} {it['name']}")
    lines.extend(factions.award(store, p, "quest_done"))
    if levels:
        lines.append(f"\n🎖 <b>Новый уровень: {p.level}!</b>")

    if f["daily"]:
        state(p).pop(str(qid), None)         # завтра можно взять снова
    else:
        state(p)[str(qid)]["done"] = True
    store.save_player(p)
    return Reply(text="\n".join(lines),
                 keyboard=[[("📜 Задания", "quests")], [("◀️ В мир", "world")]])


# ── экраны ──────────────────────────────────────────────────

def journal(p):
    """Дневник: что взято и что можно сдать."""
    refresh_daily(p)
    live = active(p)
    rows, lines = [], []
    for q in live:
        f = fields(q)
        mark = "✅" if complete(p, q) else "▫️"
        daily = " 🔄" if f["daily"] else ""
        lines.append(f"{mark} <b>{f['name']}</b>{daily}\n{goal_line(p, q)}")
        if complete(p, q):
            rows.append([(f"✅ Сдать: {f['name'][:18]}", f"qdone:{f['id']}")])
        else:
            rows.append([(f"🚮 Бросить: {f['name'][:16]}", f"qdrop:{f['id']}")])
    if not live:
        lines.append("<i>Заданий нет. Загляни к жителям Погоста — у них всегда "
                     "найдётся работа.</i>")
    rows.append([("◀️ В мир", "world"), ("◀️ Меню", "menu")])
    return Reply(text="📜 <b>Дневник заданий</b>\n\n" + "\n\n".join(lines),
                 keyboard=rows)


def offer_rows(p, npc_index):
    """Кнопки «взять задание» для диалога с NPC."""
    rows = []
    for q in available(p, npc_index):
        f = fields(q)
        tag = "🔄 " if f["daily"] else "📜 "
        rows.append([(f"{tag}{f['name']}", f"qtake:{f['id']}")])
    for q in active(p):
        f = fields(q)
        if f["npc"] == int(npc_index) and complete(p, q):
            rows.append([(f"✅ Сдать: {f['name'][:18]}", f"qdone:{f['id']}")])
    return rows


def card(p, qid):
    """Карточка задания перед принятием."""
    q = _row(qid)
    if q is None:
        return Reply(alert="Задание не найдено.")
    f = fields(q)
    return Reply(text=f"📜 <b>{f['name']}</b>\n\n<i>{f['text']}</i>\n\n{goal_line(p, q)}",
                 keyboard=[[("✔️ Взять", f"qtake:{f['id']}")],
                           [("◀️ Назад", "world")]])

files.engine/social.py:
"""Социальные экраны: отряд, надгробия и задания.

Тонкая обёртка над engine.party / engine.death / engine.quests, чтобы
роутер `engine/game.py` оставался списком команд, а не свалкой логики.
Здесь только то, что нужно всем трём: сохранить игрока после действия.
"""
from engine import (death, dungeon, factions, landmarks, party, quests,
                    stash, worldboss)
from engine.models import Reply


# ── отряд ───────────────────────────────────────────────────

def party_card(store, p):
    return party.card(store, p)


def party_new(store, p):
    return party.create(store, p)


def party_join(store, p):
    return party.accept(store, p)


def party_no(store, p):
    return party.decline(store, p)


def party_leave(store, p):
    return party.leave(store, p)


def party_invite(store, p, name):
    return party.invite(store, p, name)


def party_hint():
    return Reply(alert="Отправь: /invite Имя героя")


# ── надгробия ───────────────────────────────────────────────

def grave(store, p):
    return death.grave_card(store, p)


def claim(store, p):
    return death.claim(store, p)


# ── подземелья ──────────────────────────────────────────────

def dungeon_enter(store, p):
    return dungeon.enter(store, p)


def dungeon_view(store, p):
    return dungeon.view(store, p)


def dungeon_move(store, p, direction):
    return dungeon.move(store, p, direction)


def dungeon_fight(store, p):
    return dungeon.fight(store, p)


def dungeon_chest(store, p):
    return dungeon.open_chest(store, p)


def dungeon_down(store, p):
    return dungeon.descend(store, p)


def dungeon_exit(store, p):
    return dungeon.leave(store, p)


def dungeon_map(store, p):
    return dungeon.minimap(store, p)


def in_dungeon(p):
    return dungeon.inside(p)


# ── репутация ───────────────────────────────────────────────

def reputation(store, p):
    return factions.card(store, p)


# ── мировой босс ────────────────────────────────────────────

def boss_alive(store):
    return worldboss.active(store) is not None


def boss(store, p):
    return worldboss.card(store, p)


def boss_hit(store, p):
    return worldboss.strike(store, p)


# ── достопримечательности ───────────────────────────────────

def study(store, p, cell):
    return landmarks.claim(store, p, cell)


# ── защищённый карман ───────────────────────────────────────

def stash_view(store, p):
    return stash.view(p, store=store)


def stash_put(store, p, pos):
    r = stash.put(p, pos, store=store)
    store.save_player(p)
    return r


def stash_take(store, p, pos):
    r = stash.take(p, pos, store=store)
    store.save_player(p)
    return r


# ── задания ─────────────────────────────────────────────────

def on_enter(p, loc):
    """Приход в локацию засчитывает задания-разведки."""
    return quests.on_enter(p, loc)


def journal(p):
    return quests.journal(p)


def quest_take(store, p, qid):
    r = quests.take(p, qid)
    store.save_player(p)
    return r


def quest_drop(store, p, qid):
    r = quests.abandon(p, qid)
    store.save_player(p)
    return r


def quest_done(store, p, qid):
    return quests.hand_in(store, p, qid)


def quest_card(p, qid):
    return quests.card(p, qid)

files.engine/permissions.py:
"""Права доступа к админке: отдельные функции + ранги, как в кланах MMO.

Ранг — это просто пресет набора «капабилити». Любой ранг можно донастроить
галочками: выдать гейм-мастеру рассылку, забрать у модератора удаление и т.д.
"""
import random
import string

# (ключ, подпись, группа)
CAPS = [
    ("view_dash",    "📊 Видеть сводку",            "Просмотр"),
    ("view_players", "👥 Видеть игроков",           "Просмотр"),
    ("view_world",   "🗺 Видеть карту мира",        "Просмотр"),
    ("view_content", "📦 Видеть контент",           "Просмотр"),
    ("edit_players", "✏️ Править статы игроков",    "Игроки"),
    ("heal_players", "💊 Лечить игроков",           "Игроки"),
    ("give_items",   "🎁 Выдавать предметы",        "Игроки"),
    ("del_players",  "🗑 Удалять игроков",          "Игроки"),
    ("edit_world",   "🧱 Править клетки мира",      "Мир"),
    ("regen_world",  "🎲 Пересоздавать мир",        "Мир"),
    ("dungeons",     "🕳 Порталы и подземелья",     "Мир"),
    ("cataclysms",   "🌋 Насылать катаклизмы",      "Мир"),
    ("edit_content", "📝 Править контент игры",     "Контент"),
    ("bot_control",  "🤖 Запуск/остановка бота",    "Система"),
    ("broadcast",    "📣 Рассылка игрокам",         "Система"),
    ("settings",     "⚙️ Настройки, экспорт, сброс", "Система"),
    ("grant_admin",  "👑 Выдавать доступ другим",   "Система"),
]

CAP_KEYS = [k for k, _, _ in CAPS]
CAP_LABELS = {k: lbl for k, lbl, _ in CAPS}
CAP_GROUPS = []
for _k, _lbl, _g in CAPS:
    if _g not in CAP_GROUPS:
        CAP_GROUPS.append(_g)

# Ранги: (подпись, пресет капабилити)
RANKS = {
    "viewer": ("👁 Наблюдатель", [
        "view_dash", "view_players", "view_world", "view_content"]),
    "moderator": ("🛡 Модератор", [
        "view_dash", "view_players", "view_world", "view_content",
        "heal_players", "give_items"]),
    "gamemaster": ("🎲 Гейм-мастер", [
        "view_dash", "view_players", "view_world", "view_content",
        "edit_players", "heal_players", "give_items",
        "edit_world", "dungeons", "cataclysms", "edit_content", "broadcast"]),
    "admin": ("👑 Администратор", list(CAP_KEYS)),
}

RANK_KEYS = ["viewer", "moderator", "gamemaster", "admin"]


def rank_title(rank):
    return RANKS.get(rank, RANKS["viewer"])[0]


def rank_caps(rank):
    """Пресет капабилити ранга."""
    return list(RANKS.get(rank, RANKS["viewer"])[1])


def caps_of(player):
    """Итоговый набор прав игрока: индивидуальный список либо пресет ранга."""
    if not getattr(player, "is_web_admin", False):
        return set()
    custom = getattr(player, "web_admin_caps", None)
    if custom:
        return {c for c in custom if c in CAP_LABELS}
    return set(rank_caps(getattr(player, "web_admin_role", "viewer")))


def can(player, cap):
    return cap in caps_of(player)


def can_any(player, *caps):
    mine = caps_of(player)
    return any(c in mine for c in caps)


def new_password(length=8):
    """Читаемый пароль без похожих символов (0/O, 1/l)."""
    alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789"
    try:
        import secrets
        pick = secrets.choice
    except Exception:                              # pragma: no cover
        pick = random.choice
    return "".join(pick(alphabet) for _ in range(length))


def summary(player):
    """Короткая сводка прав для показа игроку в боте."""
    mine = caps_of(player)
    if not mine:
        return "—"
    return "\n".join(f"• {CAP_LABELS[k]}" for k in CAP_KEYS if k in mine)


def slug(text):
    """Безопасный ключ из произвольной строки (для id элементов формы)."""
    return "".join(ch if ch in string.ascii_letters + string.digits else "_"
                   for ch in str(text))


def normalize_url(raw):
    """https://host без хвостового слэша. Пустая строка, если ничего не ввели."""
    url = (raw or "").strip()
    if not url:
        return ""
    if not url.startswith(("http://", "https://")):
        url = "https://" + url
    return url.rstrip("/")


def login_url(base, tg_id):
    """Ссылка входа в панель для инлайн-кнопки бота."""
    base = normalize_url(base)
    return f"{base}/admin-login?uid={tg_id}" if base else ""

files.engine/mapview.py:
"""Карта локации для игрока: плитки-эмодзи и туман войны.

Никаких «#», «.», «@» — карта собирается из цветных квадратов, а неисследованные
клетки скрыты туманом. Игрок открывает мир, проходя по нему.
"""
from engine import data
from engine import world as W
from engine.models import Reply

TILE = {
    "grass": "🟩",
    "forest": "🌲",
    "road": "🟧",
    "water": "🟦",
    "wall": "⬛",
    "village": "🏠",
    "cave": "🟪",
}

FOG = "⬜"        # не исследовано
PLAYER = "🔴"     # ты
OTHER = "🔵"      # другой герой
DOOR = "🚪"       # переход в соседнюю локацию
PORTAL = "🌀"     # открытый портал в подземелье
CHEST = "📦"
MOB = "👾"
NPC = "💬"
GRAVE = "🪦"      # чьё-то надгробие с золотом
STAIRS = "🪜"
MARK = "❇️"       # неизученная достопримечательность


def ckey(loc, x, y, floor=0):
    return f"{loc}:{x}:{y}" if not floor else f"{loc}:{floor}:{x}:{y}"


def mark_visited(p, loc=None, x=None, y=None):
    """Отмечает клетку как исследованную вместе с соседями (радиус обзора 1)."""
    loc = p.loc if loc is None else loc
    x = p.x if x is None else x
    y = p.y if y is None else y
    floor = getattr(p, "floor", 0)
    seen = set(getattr(p, "visited", []) or [])
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            nx, ny = x + dx, y + dy
            if 0 <= nx < W.SIZE and 0 <= ny < W.SIZE:
                seen.add(ckey(loc, nx, ny, floor))
    p.visited = sorted(seen)


def is_visited(p, loc, x, y, floor=0):
    return ckey(loc, x, y, floor) in set(getattr(p, "visited", []) or [])


def others_here(store, p, loc=None, x=None, y=None):
    """Другие герои в клетке. Пустой список, если хранилища нет."""
    if store is None:
        return []
    loc = p.loc if loc is None else loc
    return [q for q in store.players.values()
            if q.created_char and q.tg_id != p.tg_id and q.loc == loc
            and (x is None or (q.x == x and q.y == y))]


def other_keys(store, p):
    """{ключ клетки: [герои]} — где сейчас стоят остальные в этой локации."""
    out = {}
    for q in others_here(store, p):
        out.setdefault(ckey(q.loc, q.x, q.y, getattr(q, "floor", 0)), []).append(q)
    return out


def _mark_keys(store, p):
    """Неизученные достопримечательности: изученные больше не мигают."""
    if store is None:
        return set()
    from engine import landmarks
    seen = set(getattr(p, "landmarks", None) or [])
    return landmarks.keys(store) - seen


def _grave_keys(store):
    if store is None:
        return set()
    from engine import death
    return death.keys(store)


def portal_keys(store):
    """Ключи клеток, где сейчас открыты порталы подземелий."""
    out = {}
    for tpl in store.settings.get("dungeon_templates", []) or []:
        key = tpl.get("portal_cell")
        if key:
            out[key] = tpl
    return out


def glyph(cell, portals=(), graves=(), marks=()):
    """Символ клетки на карте (без учёта тумана и позиции игрока)."""
    if cell is None or not cell.passable:
        return TILE["wall"]
    if cell.key in graves:
        return GRAVE
    if cell.key in marks:
        return MARK
    if cell.key in portals:
        return PORTAL
    if cell.link:
        return STAIRS if len(cell.link) >= 4 and cell.link[0] == cell.loc else DOOR
    if cell.mob >= 0:
        return MOB
    if cell.npc >= 0:
        return NPC
    if cell.chest:
        return CHEST
    return TILE.get(cell.tile, TILE["grass"])


def grid(p, cells, portals=(), others=None, graves=(), marks=()):
    """Список строк карты текущей локации игрока.

    `others` — {ключ: [герои]}: соседи видны синей точкой, но только в уже
    изученных клетках, иначе карта выдавала бы содержимое тумана.
    """
    others = others or {}
    rows = []
    for x in range(W.SIZE):
        row = ""
        for y in range(W.SIZE):
            if (x, y) == (p.x, p.y):
                row += PLAYER
                continue
            if not is_visited(p, p.loc, x, y, getattr(p, "floor", 0)):
                row += FOG
                continue
            if others.get(ckey(p.loc, x, y)):
                row += OTHER
                continue
            row += glyph(cells.get(ckey(p.loc, x, y, getattr(p, "floor", 0))), portals, graves, marks)
        rows.append(row)
    return rows


def render(p, cells, store=None):
    """Reply с картой локации: туман войны, легенда, прогресс исследования."""
    portals = portal_keys(store) if store is not None else {}
    others = other_keys(store, p) if store is not None else {}
    graves = _grave_keys(store)
    marks = _mark_keys(store, p)
    rows = grid(p, cells, portals, others, graves, marks)

    floor = getattr(p, "floor", 0)
    total = sum(1 for c in cells.values() if c.loc == p.loc and c.floor == floor)
    prefix = f"{p.loc}:" if floor == 0 else f"{p.loc}:{floor}:"
    seen = sum(1 for k in (getattr(p, "visited", []) or []) if k.startswith(prefix))
    pct = int(seen / total * 100) if total else 0

    loc = data.LOCATIONS[p.loc] if p.loc < len(data.LOCATIONS) else ("Неизвестность",)
    legend = (f"{PLAYER} ты · {OTHER} герой · {FOG} не изучено · "
              f"{TILE['wall']} стена · {DOOR} переход · {STAIRS} лестница\n"
              f"{PORTAL} портал · {MOB} враг · {NPC} житель · {CHEST} сундук · "
              f"{GRAVE} могила · {MARK} диковина")

    nearby = len(others)
    company = f" · {OTHER} рядом героев: {nearby}" if nearby else ""
    found_marks = ""
