"""Админ-операции над миром: катаклизмы и мировые боссы.

Вынесено из engine/adminops.py, чтобы тот не разрастался. Проверка прав
и запись в журнал — те же самые, через общие require()/Denied.
"""
from engine.adminops import Denied, require

# ── катаклизмы ──────────────────────────────────────────────

def cataclysm_strike(store, actor, kind_key, loc=-1, hours=None, source="panel"):
    """Обрушить бедствие на локацию (loc=-1 — на весь мир)."""
    require(actor, "cataclysms")
    from engine import cataclysm
    try:
        ev = cataclysm.strike(store, kind_key, loc, actor=actor,
                              source=source, hours=hours)
    except ValueError as e:
        raise Denied(str(e))
    return ev, f"{cataclysm.title(kind_key)} → {cataclysm.place(loc)}"


def cataclysm_end(store, actor, event_id, source="panel"):
    require(actor, "cataclysms")
    from engine import cataclysm
    ev = cataclysm.end(store, event_id, revert=True, actor=actor, source=source)
    if ev is None:
        raise Denied("Бедствие уже утихло")
    return ev, cataclysm.title(ev["kind"])


def cataclysm_calm(store, actor, source="panel"):
    """Погасить все бедствия разом и вернуть клетки как было."""
    require(actor, "cataclysms")
    from engine import cataclysm
    live = cataclysm.active(store, None)
    for ev in list(live):
        cataclysm.end(store, ev["id"], revert=True, actor=actor, source=source)
    return len(live)


# ── мировые боссы ───────────────────────────────────────────

def boss_summon(store, actor, key, loc=None, hours=None, source="panel"):
    require(actor, "cataclysms")
    from engine import worldboss
    try:
        ev = worldboss.summon(store, key, loc, actor=actor, source=source,
                              hours=hours)
    except ValueError as e:
        raise Denied(str(e))
    return ev, worldboss.title(key)


def boss_dismiss(store, actor, source="panel"):
    require(actor, "cataclysms")
    from engine import worldboss
    ev = worldboss.dismiss(store, actor, source)
    if ev is None:
        raise Denied("Босса и так нет")
    return ev, worldboss.title(ev["key"])

files.engine/adminmenu.py:
"""Экраны админки внутри бота. Только сборка Reply — работу делает adminops."""
import random

from engine import adminops, audit, data, itemui, permissions, rules
from engine.models import Reply

PAGE = 6                    # игроков на страницу списка


def sections(p):
    """Кнопки разделов админки — только те, на которые есть права."""
    rows = []
    if permissions.can_any(p, "view_dash", "view_players"):
        rows.append([("📊 Сводка", "adm:stats"), ("👥 Игроки", "adm:players:0")])
    line = []
    if permissions.can(p, "dungeons"):
        line.append(("🕳 Порталы", "adm:portals"))
    if permissions.can(p, "cataclysms"):
        line.append(("🌋 Катаклизмы", "adm:cata"))
    if permissions.can(p, "broadcast"):
        line.append(("📣 Рассылка", "adm:cast"))
    if line:
        rows.append(line)
    if permissions.can_any(p, "view_content", "edit_content"):
        rows.append([("📦 Контент", "adm:content")])
    rows.append([("📜 Журнал действий", "adm:audit:0")])
    return rows


def _back(extra=None):
    rows = list(extra or [])
    rows.append([("◀️ Админка", "admin")])
    return rows


def _deny(exc):
    return Reply(alert=str(exc) or "Недостаточно прав")


# ── сводка ──────────────────────────────────────────────────

def stats(p, store):
    if not permissions.can_any(p, "view_dash", "view_players"):
        return Reply(alert="Нет права смотреть сводку.")
    s = store.stats()
    portals = sum(1 for t in adminops.templates(store) if t.get("portal_cell"))
    admins = sum(1 for q in store.players.values() if q.is_web_admin)
    text = (
        "📊 <b>Сводка мира</b>\n\n"
        f"👥 Игроков: <b>{s['players']}</b> · героев: <b>{s['heroes']}</b>\n"
        f"⭐ Средний уровень: <b>{s['avg_level']}</b>\n"
        f"🪙 Золота в мире: <b>{s['gold']}</b>\n"
        f"☠️ Убито мобов: <b>{s['kills']}</b>\n"
        f"🧱 Клеток мира: <b>{s['cells']}</b>\n"
        f"🌀 Открытых порталов: <b>{portals}</b>\n"
        f"👑 Админов: <b>{admins}</b>\n\n"
        f"<i>Данные общие с веб-панелью.</i>")
    return Reply(text=text, keyboard=_back([[("🔄 Обновить", "adm:stats")]]))


# ── игроки ──────────────────────────────────────────────────

def players(p, store, page=0):
    if not permissions.can(p, "view_players"):
        return Reply(alert="Нет права смотреть игроков.")
    ps = sorted(store.players.values(), key=lambda q: (-q.level, q.name))
    page = max(0, int(page or 0))
    total = max(1, (len(ps) + PAGE - 1) // PAGE)
    page = min(page, total - 1)
    chunk = ps[page * PAGE:(page + 1) * PAGE]

    rows = [[(f"{'👑 ' if q.is_web_admin else ''}{q.name} · ур.{q.level}",
              f"adm:p:{q.tg_id}")] for q in chunk]
    nav = []
    if page > 0:
        nav.append(("◀️", f"adm:players:{page - 1}"))
    nav.append((f"{page + 1}/{total}", "adm:noop"))
    if page < total - 1:
        nav.append(("▶️", f"adm:players:{page + 1}"))
    if len(nav) > 1:
        rows.append(nav)

    text = (f"👥 <b>Игроки</b> ({len(ps)})\n\n"
            + ("\n".join(f"• {q.name} — ур. {q.level} · {q.gold}🪙 · "
                         f"{'герой' if q.created_char else 'без героя'}"
                         for q in chunk) or "<i>Пока никого.</i>"))
    return Reply(text=text, keyboard=_back(rows))


def player_card(p, store, tg_id):
    if not permissions.can(p, "view_players"):
        return Reply(alert="Нет права смотреть игроков.")
    q = store.players.get(int(tg_id))
    if not q:
        return Reply(alert="Игрок не найден.")
    s = rules.stats(q)
    where = data.LOCATIONS[q.loc][0] if q.loc < len(data.LOCATIONS) else "—"
    role = permissions.rank_title(q.web_admin_role) if q.is_web_admin else "—"
    text = (
        f"👤 <b>{q.name}</b> <code>#{q.tg_id}</code>\n\n"
        f"Класс: {q.cls or '—'} · ур. <b>{q.level}</b>\n"
        f"❤️ {q.hp}/{s['max_hp']} · 💙 {q.mp}/{s['max_mp']}\n"
        f"🪙 {q.gold} · 🎒 {len(q.inventory)} предм. · ☠️ {q.kills}\n"
        f"📍 {where} [{q.x},{q.y}]\n"
        f"👑 Доступ: {role}")

    rows = []
    line = []
    if permissions.can(p, "heal_players"):
        line.append(("💊 Исцелить", f"adm:heal:{q.tg_id}"))
    if permissions.can(p, "give_items"):
        line.append(("🎁 Предмет", f"adm:gift:{q.tg_id}"))
    if line:
        rows.append(line)
    if permissions.can(p, "edit_players"):
        rows.append([("🪙 +100", f"adm:gold:{q.tg_id}:100"),
                     ("🪙 −100", f"adm:gold:{q.tg_id}:-100")])
        rows.append([("⭐ +1 ур.", f"adm:lvl:{q.tg_id}:1"),
                     ("⭐ −1 ур.", f"adm:lvl:{q.tg_id}:-1")])
        rows.append([("🏠 В деревню", f"adm:tp:{q.tg_id}")])
    if permissions.can(p, "grant_admin"):
        if q.is_web_admin:
            rows.append([("🔑 Новый пароль", f"adm:pass:{q.tg_id}"),
                         ("🚫 Отозвать", f"adm:revoke:{q.tg_id}")])
        else:
            rows.append([("👑 Выдать доступ", f"adm:grant:{q.tg_id}")])
    if permissions.can(p, "del_players"):
        rows.append([("🗑 Удалить игрока", f"adm:del:{q.tg_id}")])
    rows.append([("◀️ К списку", "adm:players:0")])
    return Reply(text=text, keyboard=_back(rows))


def gift_menu(p, store, tg_id):
    if not permissions.can(p, "give_items"):
        return Reply(alert="Нет права выдавать предметы.")
    q = store.players.get(int(tg_id))
    if not q:
        return Reply(alert="Игрок не найден.")
    goods = itemui.stock()
    entries, _ = itemui.slice_page(goods, 0)
    lines = [f"🎁 <b>Выдать предмет</b>", f"Получатель: <b>{q.name}</b>", ""]
    for num, _pos, idx in entries:
        lines.append(itemui.line(num, idx, itemui.type_label(rules.item(idx))))
    lines.append("")
    lines.append("<i>Нажми номер — предмет уйдёт игроку.</i>")

    rows, row = [], []
    for num, _pos, idx in entries:
        row.append((f"{itemui.digit(num)}{rules.item(idx)['icon']}",
                    f"adm:give:{tg_id}:{idx}"))
        if len(row) == itemui.PER_ROW:
            rows.append(row)
            row = []
    if row:
        rows.append(row)
    rows.append([("◀️ Назад", f"adm:p:{tg_id}")])
    return Reply(text="\n".join(lines), keyboard=rows)


def grant_menu(p, store, tg_id):
    if not permissions.can(p, "grant_admin"):
        return Reply(alert="Нет права выдавать доступ.")
    q = store.players.get(int(tg_id))
    if not q:
        return Reply(alert="Игрок не найден.")
    rows = [[(permissions.rank_title(r), f"adm:rank:{tg_id}:{r}")]
            for r in permissions.RANK_KEYS]
    rows.append([("◀️ Назад", f"adm:p:{tg_id}")])
    return Reply(text=(f"👑 <b>Выдать доступ</b>\n\nИгрок: <b>{q.name}</b>\n\n"
                       "Выбери ранг. Точечные права потом можно донастроить "
                       "галочками в веб-панели."), keyboard=rows)


# ── порталы ─────────────────────────────────────────────────

def portals(p, store):
    if not permissions.can(p, "dungeons"):
        return Reply(alert="Нет права управлять порталами.")
    tpls = adminops.templates(store)
    lines, rows = [], []
    for t in tpls:
        key = t.get("portal_cell")
        if key:
            cl, cx, cy = map(int, key.split(":"))
            where = data.LOCATIONS[cl][0] if cl < len(data.LOCATIONS) else "?"
            lines.append(f"🌀 <b>{t['name']}</b>\n   открыт: {where} [{cx},{cy}]")
            rows.append([(f"❌ Закрыть: {t['name'][:18]}", f"adm:pclose:{t['id']}")])
        else:
            lines.append(f"⚫ <b>{t['name']}</b>\n   закрыт · ур. {t.get('min_level', 1)}+")
            rows.append([(f"🚪 Открыть: {t['name'][:18]}", f"adm:popen:{t['id']}")])
    text = ("🕳 <b>Порталы подземелий</b>\n\n"
            + ("\n\n".join(lines) if lines else "<i>Шаблонов нет.</i>")
            + "\n\n<i>Открытие/закрытие видно и в веб-панели.</i>")
    return Reply(text=text, keyboard=_back(rows))


def cataclysms(p, store):
    """Экран бедствий в боте: что бушует и чем ударить."""
    from engine import cataclysm as C

    if not permissions.can(p, "cataclysms"):
        return Reply(alert="Нет права насылать катаклизмы.")
    live = C.active(store, None)
    lines, rows = [], []
    for e in live:
        left = max(0, int(e["until"] - __import__("time").time())) // 60
        lines.append(f"{C.title(e['kind'])}\n   {C.place(e['loc'])} · ещё {left} мин"
                     f" · {e.get('cells', 0)} кл.")
        rows.append([(f"🕊 Прекратить: {C.KINDS[e['kind']]['name'][:16]}",
                      f"adm:cataoff:{e['id']}")])
    for i in range(0, len(C.ORDER), 2):
        rows.append([(C.title(k), f"adm:catahit:{k}") for k in C.ORDER[i:i + 2]])
    text = ("🌋 <b>Катаклизмы</b>\n\n"
            + ("\n\n".join(lines) if lines else "<i>Сейчас всё спокойно.</i>")
            + "\n\n<i>Удар накрывает случайную локацию; тонкая настройка — "
              "в веб-панели, вкладка «Мир → Катаклизмы».</i>")
    return Reply(text=text, keyboard=_back(rows))


def pick_loc(store):
    """Случайная локация для удара из бота."""
    return random.randrange(len(data.LOCATIONS)) if data.LOCATIONS else 0


def pick_cell(store):
    """Случайная пустая проходимая клетка под портал."""
    free = [k for k, c in store.world.items()
            if c.passable and not c.link and c.npc < 0 and c.mob < 0 and not c.chest]
    return random.choice(free) if free else ""


# ── контент и журнал ────────────────────────────────────────

def content(p, store):
    if not permissions.can_any(p, "view_content", "edit_content"):
        return Reply(alert="Нет права смотреть контент.")
    text = (
        "📦 <b>Контент игры</b>\n\n"
        f"👾 Мобов: <b>{len(data.MOBS)}</b>\n"
        f"🗡 Предметов: <b>{len(data.ITEMS)}</b>\n"
        f"💬 NPC: <b>{len(data.NPCS)}</b>\n"
        f"🎭 Классов: <b>{len(data.CLASSES)}</b>\n"
        f"🗺 Локаций: <b>{len(data.LOCATIONS)}</b>\n\n"
        "<i>Правка контента — в веб-панели, вкладка «Контент».</i>")
    return Reply(text=text, keyboard=_back())


def audit_log(p, store, page=0):
    items = audit.entries(store)
    page = max(0, int(page or 0))
    total = max(1, (len(items) + 5 - 1) // 5)
    page = min(page, total - 1)
    chunk = items[page * 5:(page + 1) * 5]
    body = "\n\n".join(audit.line(e) for e in chunk) or "<i>Журнал пуст.</i>"
    rows = []
    nav = []
    if page > 0:
        nav.append(("◀️", f"adm:audit:{page - 1}"))
    nav.append((f"{page + 1}/{total}", "adm:noop"))
    if page < total - 1:
        nav.append(("▶️", f"adm:audit:{page + 1}"))
    if len(nav) > 1:
        rows.append(nav)
    rows.append([("🔄 Обновить", "adm:audit:0")])
    return Reply(text=f"📜 <b>Действия админов</b> ({len(items)})\n\n{body}",
                 keyboard=_back(rows))

files.engine/adminbot.py:
"""Админ-раздел внутри самого бота: те же функции, что и в веб-панели.

Действия выполняются через engine.adminops, поэтому бот и панель работают
с одним состоянием и пишут в общий журнал (engine.audit).
"""
from engine import adminmenu, permissions, texts
from engine.models import Reply


def _keyboard(p, store, first_row):
    """Кнопки админки. Ссылка на панель берётся из настроек (может быть пустой)."""
    rows = [first_row]
    url = permissions.login_url(store.settings.get("panel_url", ""), p.tg_id)
    if url:
        rows.append([("🌐 Открыть панель", {"url": url})])
    rows.append([("◀️ Меню", "menu")])
    return rows


def panel(p, store):
    """Главный экран админки в боте: разделы по правам + доступ."""
    if not p.is_web_admin:
        return Reply(alert="У тебя нет доступа к админке.")
    rows = adminmenu.sections(p)
    rows.append([("🔑 Логин и пароль", "adminpass")])
    url = permissions.login_url(store.settings.get("panel_url", ""), p.tg_id)
    if url:
        rows.append([("🌐 Открыть панель", {"url": url})])
    rows.append([("◀️ Меню", "menu")])
    return Reply(text=texts.admin_panel(p), keyboard=rows)


def password(p, store):
    if not p.is_web_admin:
        return Reply(alert="У тебя нет доступа к админке.")
    if not p.web_admin_password:
        p.web_admin_password = permissions.new_password()
        store.save_player(p)
    return Reply(text=texts.admin_password(p),
                 keyboard=_keyboard(p, store, [("🛠 Админка", "admin")]))


def grant(store, p, rank="viewer", caps=None, reset_password=True):
    """Выдаёт/обновляет доступ. Возвращает текст уведомления для игрока."""
    p.is_web_admin = True
    p.web_admin_role = rank if rank in permissions.RANKS else "viewer"
    p.web_admin_caps = list(caps) if caps else []
    if reset_password or not p.web_admin_password:
        p.web_admin_password = permissions.new_password()
    p.admin_notified = False
    store.save_player(p)
    return texts.admin_granted(p)


def revoke(store, p):
    p.is_web_admin = False
    p.web_admin_caps = []
    p.web_admin_password = ""
    p.admin_notified = False
    store.save_player(p)
    return texts.admin_revoked()

files.engine/adminroute.py:
"""Роутер админ-действий в боте: callback `adm:<команда>:<аргументы>`."""
from engine import adminmenu, adminops
from engine.models import Reply

SRC = "bot"


def handle(p, store, arg):
    """arg — часть callback после `adm:`. Возвращает Reply."""
    if not p.is_web_admin:
        return Reply(alert="У тебя нет доступа к админке.")
    head, _, rest = (arg or "").partition(":")
    fn = ROUTES.get(head)
    if fn is None:
        return Reply(alert="Неизвестное действие админки.")
    try:
        return fn(p, store, rest)
    except adminops.Denied as e:
        return Reply(alert=str(e))
    except Exception as e:                                    # не роняем бота
        return Reply(alert=f"Ошибка: {e}")


def text_input(p, store, text):
    """Ожидаемый от админа свободный текст (сейчас — тело рассылки)."""
    if getattr(p, "pending", "") != "broadcast":
        return None
    p.pending = ""
    store.save_player(p)
    body = (text or "").strip()
    if not body:
        return Reply(text="Пустое сообщение — рассылка отменена.",
                     keyboard=[[("◀️ Админка", "admin")]])
    try:
        _, n = adminops.broadcast(store, p, body, SRC)
    except adminops.Denied as e:
        return Reply(text=f"❌ {e}", keyboard=[[("◀️ Админка", "admin")]])
    return Reply(text=f"📣 Рассылка поставлена в очередь: <b>{n}</b> получателей.",
                 keyboard=[[("📜 Журнал", "adm:audit:0")], [("◀️ Админка", "admin")]],
                 new_message=True)


def _int(rest, default=0):
    try:
        return int(str(rest).split(":")[0])
    except (ValueError, IndexError):
        return default


# ── экраны ──────────────────────────────────────────────────

def _stats(p, store, rest):
    return adminmenu.stats(p, store)


def _players(p, store, rest):
    return adminmenu.players(p, store, _int(rest))


def _card(p, store, rest):
    return adminmenu.player_card(p, store, _int(rest))


def _gift(p, store, rest):
    return adminmenu.gift_menu(p, store, _int(rest))


def _grant_menu(p, store, rest):
    return adminmenu.grant_menu(p, store, _int(rest))


def _portals(p, store, rest):
    return adminmenu.portals(p, store)


def _content(p, store, rest):
    return adminmenu.content(p, store)


def _cata(p, store, rest):
    return adminmenu.cataclysms(p, store)


def _cata_hit(p, store, rest):
    """Удар из бота: бедствие по случайной локации, срок по умолчанию."""
    kind_key = str(rest).split(":")[0]
    adminops.cataclysm_strike(store, p, kind_key, adminmenu.pick_loc(store),
                              source=SRC)
    return adminmenu.cataclysms(p, store)


def _cata_off(p, store, rest):
    adminops.cataclysm_end(store, p, _int(rest), source=SRC)
    return adminmenu.cataclysms(p, store)


def _audit(p, store, rest):
    return adminmenu.audit_log(p, store, _int(rest))


def _cast(p, store, rest):
    from engine import permissions
    if not permissions.can(p, "broadcast"):
        return Reply(alert="Нет права на рассылку.")
    p.pending = "broadcast"
    store.save_player(p)
    return Reply(text=("📣 <b>Рассылка игрокам</b>\n\n"
                       "Пришли следующим сообщением текст — я разошлю его всем.\n"
                       "HTML разрешён. Отмена — кнопка ниже."),
                 keyboard=[[("✖️ Отмена", "adm:castoff")], [("◀️ Админка", "admin")]])


def _cast_off(p, store, rest):
    p.pending = ""
    store.save_player(p)
    return Reply(text="Рассылка отменена.", keyboard=[[("◀️ Админка", "admin")]])


def _noop(p, store, rest):
    return Reply(alert="")


# ── действия ────────────────────────────────────────────────

def _heal(p, store, rest):
    adminops.heal(store, p, _int(rest), SRC)
    r = adminmenu.player_card(p, store, _int(rest))
    r.alert = "Игрок исцелён"
    return r


def _give(p, store, rest):
    parts = str(rest).split(":")
    tg_id, idx = _int(parts[0]), _int(parts[1] if len(parts) > 1 else 0)
    _, info = adminops.give_item(store, p, tg_id, idx, SRC)
    r = adminmenu.player_card(p, store, tg_id)
    r.alert = f"Выдано: {info}"
    return r


def _gold(p, store, rest):
    parts = str(rest).split(":")
    tg_id, amount = _int(parts[0]), _int(parts[1] if len(parts) > 1 else 0)
    adminops.add_gold(store, p, tg_id, amount, SRC)
    r = adminmenu.player_card(p, store, tg_id)
    r.alert = f"Золото: {amount:+d}"
    return r


def _level(p, store, rest):
    parts = str(rest).split(":")
    tg_id, delta = _int(parts[0]), _int(parts[1] if len(parts) > 1 else 0)
    adminops.add_level(store, p, tg_id, delta, SRC)
    r = adminmenu.player_card(p, store, tg_id)
    r.alert = f"Уровень: {delta:+d}"
    return r


def _tp(p, store, rest):
    from engine import world as W
    tg_id = _int(rest)
    adminops.teleport(store, p, tg_id, 0, W.SPAWN[0], W.SPAWN[1], SRC)
    r = adminmenu.player_card(p, store, tg_id)
    r.alert = "Игрок телепортирован в деревню"
    return r


def _del(p, store, rest):
    tg_id = _int(rest)
    adminops.delete_player(store, p, tg_id, SRC)
    r = adminmenu.players(p, store, 0)
    r.alert = "Игрок удалён"
    return r


def _rank(p, store, rest):
    parts = str(rest).split(":")
    tg_id = _int(parts[0])
    rank = parts[1] if len(parts) > 1 else "viewer"
    adminops.grant(store, p, tg_id, rank, None, SRC)
    r = adminmenu.player_card(p, store, tg_id)
    r.alert = "Доступ выдан"
    return r


def _revoke(p, store, rest):
    tg_id = _int(rest)
    adminops.revoke(store, p, tg_id, SRC)
    r = adminmenu.player_card(p, store, tg_id)
    r.alert = "Доступ отозван"
    return r


def _newpass(p, store, rest):
    tg_id = _int(rest)
    adminops.new_password(store, p, tg_id, SRC)
    q = store.players.get(tg_id)
    r = adminmenu.player_card(p, store, tg_id)
    r.alert = f"Новый пароль: {q.web_admin_password}" if q else "Готово"
    return r


def _portal_open(p, store, rest):
    _, info = adminops.portal_open(store, p, _int(rest), adminmenu.pick_cell, SRC)
    r = adminmenu.portals(p, store)
    r.alert = f"Портал открыт: {info}"
    return r


def _portal_close(p, store, rest):
    adminops.portal_close(store, p, _int(rest), SRC)
    r = adminmenu.portals(p, store)
    r.alert = "Портал закрыт"
    return r


ROUTES = {
    "stats": _stats, "players": _players, "p": _card, "gift": _gift,
    "grant": _grant_menu, "portals": _portals, "content": _content,
    "audit": _audit, "cast": _cast, "castoff": _cast_off, "noop": _noop,
    "heal": _heal, "give": _give, "gold": _gold, "lvl": _level, "tp": _tp,
    "del": _del, "rank": _rank, "revoke": _revoke, "pass": _newpass,
    "popen": _portal_open, "pclose": _portal_close,
    "cata": _cata, "catahit": _cata_hit, "cataoff": _cata_off,
}

