            <span aria-hidden="true">{"🔄" if change_type == "change" else "⭐"}</span>
            <span>{title}</span>
          </h3>
          <time datetime="{created}" style="font-size:0.75rem; color:var(--text-muted); display:block; margin-bottom:0.75rem;">{created}</time>
          {body}
